INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES (-416.5, 1, "カリン", 2.801, 10085, 54, "2022/02/07 12:00:00", "2022/02/24 14:59:59", 3, 0, 10085003, 190801, 2, "受け取ることができる\n報酬があるようです\n確認してみてください");
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES (-416.5, 2, "カリン", 0, 10085, 54, "2022/02/07 12:00:00", "2022/02/24 14:59:59", 4, 0, 10085004, 190801, 2, "報酬がもらえますよ！\nチェックしてみてください");
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES (-416.5, 1, "カリン", 0, 10085, 57, "2022/02/07 12:00:00", "2022/02/24 14:59:59", 5, 0, 10085005, 190801, 1, "イベントお疲れ様です！\n皆さんのご活躍ぶりには\nいつも感謝しています");
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES (-363, 1, "カリン", 5.506, 10085, 55, "2022/02/07 12:00:00", "2022/02/24 14:59:59", 1, 0, 10085006, 190801, 2, "ギルド管理協会です！\n討伐証をお持ちでしたら、\n報酬交換できますよ");
