INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES (-363, 2, "カリン", 1.539, 10085, 56, "2022/02/07 12:00:00", "2022/02/24 14:59:59", 3, 0, 10085008, 190801, 1, "お疲れ様でした\n討伐証の交換、\nお忘れないように！");
INSERT INTO `v1_463f7751101cd6250f5e1a5901fcf5ac7eeafe8b364ee77a282bd5b59923f3a1` VALUES (-363, 2, "カリン", 1.875, 10085, 56, "2022/02/07 12:00:00", "2022/02/24 14:59:59", 4, 0, 10085009, 190801, 1, "終わっちゃいましたねー\n討伐証は努力の証！\n報酬と交換しましょう！");
